  let lon = L0 + C;
  const omega = (125.04 - 1934.136*T) * Math.PI / 180;
  lon = lon - 0.00569 - 0.00478*Math.sin(omega);
  return ((lon % 360) + 360) % 360;
}

// ─── Build ecliptic strip ─────────────────────────────────────────────────────
const TOTAL_DAYS = SIGNS.reduce((a,s)=>a+s.days,0); // ~365

function buildStrip() {
  const strip = document.getElementById('eclipticStrip');
  strip.innerHTML = '';
  let left = 0;
  for (const s of SIGNS) {
    const pct = (s.days / TOTAL_DAYS) * 100;
    const band = document.createElement('div');
    band.className = 'constellation-band' + (s.id==='ophiuchus'?' ophiuchus':'') + (s.id==='scorpius'?' scorpius':'');
    band.id = 'band_'+s.id;
    band.style.cssText = `left:${left}%;width:${pct}%`;
    band.innerHTML = `<span>${s.id==='scorpius'?'⛏':s.symbol}</span>`;
    band.title = `${s.name}: ${s.date_approx} (${s.days} days)`;
    strip.appendChild(band);
    left += pct;
  }
  const sun = document.createElement('div');
  sun.className = 'sun-marker';
  sun.id = 'sunMarker';
  strip.appendChild(sun);
}

function positionSun(lon) {
  // Map ecliptic longitude 0–360 to % position along the strip
  // Strip runs left=Capricornus (lon 299.5) around the ecliptic
  // We'll map by sign position in the SIGNS array order
  let totalBefore = 0;
  for (const s of SIGNS) {
    let inSign = false;
    if (s.id === 'pisces') { inSign = lon>=351.5||lon<28.5; }
    else { inSign = lon>=s.lon_start && lon<s.lon_end; }
    if (inSign) {
      let frac;
      if (s.id === 'pisces') {
        const adj = lon>=351.5 ? lon-351.5 : lon+(360-351.5);
        frac = adj / (s.lon_end-s.lon_start+360-s.lon_start);
        frac = Math.min(frac, 1);
      } else {
        frac = (lon - s.lon_start) / (s.lon_end - s.lon_start);
      }
      const pct = ((totalBefore + s.days*frac) / TOTAL_DAYS) * 100;
      const marker = document.getElementById('sunMarker');
      marker.style.left = pct+'%';
      marker.style.display = 'block';
      return;
    }
    totalBefore += s.days;
  }
}

function highlightBand(signId) {
  document.querySelectorAll('.constellation-band').forEach(b=>b.classList.remove('active'));
  const b = document.getElementById('band_'+signId);
  if (b) b.classList.add('active');
}

// ─── Build reference table ────────────────────────────────────────────────────
function buildTable() {
  const tbody = document.getElementById('allSignsBody');
  for (const s of SIGNS) {
    const tr = document.createElement('tr');
    if (s.id==='ophiuchus') tr.className='oph';
    if (s.id==='scorpius')  tr.className='sco';
    tr.innerHTML = `<td>${s.name}</td><td>${s.symbol}</td>
      <td>${s.date_approx.split('–')[0].trim()}</td>
      <td>${s.date_approx.split('–')[1]?.trim()||''}</td>
      <td class="dur">${s.days}d</td>
      <td class="trad">${s.trad}</td>`;
    tbody.appendChild(tr);
  }
}

function toggleTable() {
  const t = document.getElementById('allSigns');
  t.classList.toggle('open');
  document.querySelector('.all-signs-toggle').textContent =
    t.classList.contains('open')
      ? '▾ Full 13-Sign Reference Table'
      : '▸ Full 13-Sign Reference Table';
}

// ─── Main calculation ─────────────────────────────────────────────────────────
function calculate() {
  const val = document.getElementById('bdate').value;
  const err = document.getElementById('errmsg');
  err.style.display = 'none';

  if (!val) { err.textContent='Enter a date.'; err.style.display='block'; return; }
  const date = new Date(val+'T12:00:00');

  const lon = solarLongitude(date);

