function getTradSign(date) {
  const m = date.getMonth() + 1, d = date.getDate();
  for (const t of TRAD) {
    const [sm,sd] = t.start, [em,ed] = t.end;
    if (sm <= em) { if ((m===sm&&d>=sd)||(m>sm&&m<em)||(m===em&&d<=ed)) return t.name; }
    else { if ((m===sm&&d>=sd)||m>sm||(m===em&&d<=ed)) return t.name; }
  }
  return 'Capricorn';
}

// ─── Jean Meeus solar longitude ───────────────────────────────────────────────
function julianDay(date) {
  let y = date.getFullYear(), m = date.getMonth()+1, d = date.getDate()+0.5;
  if (m<=2) { y--; m+=12; }
  const A = Math.floor(y/100), B = 2-A+Math.floor(A/4);
  return Math.floor(365.25*(y+4716))+Math.floor(30.6001*(m+1))+d+B-1524.5;
}

function solarLongitude(date) {
  const JD = julianDay(date);
  const T  = (JD - 2451545.0) / 36525.0;

  let L0 = 280.46646 + 36000.76983*T + 0.0003032*T*T;
  L0 = ((L0 % 360) + 360) % 360;

  let M = 357.52911 + 35999.05029*T - 0.0001537*T*T;
  M = ((M % 360) + 360) % 360;
  const Mr = M * Math.PI / 180;

  const C = (1.914602 - 0.004817*T - 0.000014*T*T)*Math.sin(Mr)
          + (0.019993 - 0.000101*T)*Math.sin(2*Mr)
          + 0.000289*Math.sin(3*Mr);

  let lon = L0 + C;
  const omega = (125.04 - 1934.136*T) * Math.PI / 180;
  lon = lon - 0.00569 - 0.00478*Math.sin(omega);
  return ((lon % 360) + 360) % 360;
}

