// ─── Rising sign / Ascendant (Meeus Ch.14) ───────────────────────────────────
function greenwichSiderealTime(JD) {
  const T = (JD - 2451545.0) / 36525.0;
  let GST = 280.46061837 + 360.98564736629*(JD-2451545.0) + 0.000387933*T*T - T*T*T/38710000;
  return ((GST % 360) + 360) % 360;
}

function calcAscendant(date, latDeg, lonDeg) {
  // Full Julian Day including time fraction
  const y=date.getFullYear(), mo=date.getMonth()+1;
  const d=date.getDate() + (date.getHours() + date.getMinutes()/60 + date.getSeconds()/3600)/24;
  let yy=y, mm=mo;
  if (mm<=2) { yy--; mm+=12; }
  const A=Math.floor(yy/100), B=2-A+Math.floor(A/4);
  const JD = Math.floor(365.25*(yy+4716))+Math.floor(30.6001*(mm+1))+d+B-1524.5;

  const GST = greenwichSiderealTime(JD);
  const LST = ((GST + lonDeg) % 360 + 360) % 360; // Local Sidereal Time in degrees (RAMC)

  const e  = (23.439291111 - 0.013004167*(JD-2451545)/36525) * Math.PI/180; // obliquity
  const lat = latDeg * Math.PI/180;
  const RAMC = LST * Math.PI/180;

  // Ascendant ecliptic longitude
  let asc = Math.atan2(-Math.cos(RAMC), Math.sin(e)*Math.tan(lat) + Math.cos(e)*Math.sin(RAMC));
  asc = asc * 180/Math.PI;
  asc = ((asc % 360) + 360) % 360;
  return asc;
}

