const TOTAL_DAYS = SIGNS.reduce((a,s)=>a+s.days,0);

function getSign(lon) {
  for (const s of SIGNS) {
    if (s.id==='pisces') { if (lon>=351.5||lon<28.5) return s; }
    else { if (lon>=s.lon_start && lon<s.lon_end) return s; }
  }
  return SIGNS[0];
}

// Traditional tropical (for comparison)
const TRAD=[
  {name:'Capricorn',start:[12,22],end:[1,19]},{name:'Aquarius',start:[1,20],end:[2,18]},
  {name:'Pisces',start:[2,19],end:[3,20]},{name:'Aries',start:[3,21],end:[4,19]},
