  {name:'Scorpio',start:[10,23],end:[11,21]},{name:'Sagittarius',start:[11,22],end:[12,21]},
];
function getTrad(date) {
  const m=date.getMonth()+1,d=date.getDate();
  for (const t of TRAD) {
    const [sm,sd]=t.start,[em,ed]=t.end;
    if(sm<=em){if((m===sm&&d>=sd)||(m>sm&&m<em)||(m===em&&d<=ed))return t.name;}
    else{if((m===sm&&d>=sd)||m>sm||(m===em&&d<=ed))return t.name;}
  } return 'Capricorn';
}

// ─── Julian Day ───────────────────────────────────────────────────────────────
function julianDay(date) {
  let y=date.getFullYear(),m=date.getMonth()+1;
  const d=date.getDate()+(date.getHours()+date.getMinutes()/60+date.getSeconds()/3600)/24;
  if(m<=2){y--;m+=12;}
  const A=Math.floor(y/100),B=2-A+Math.floor(A/4);
  return Math.floor(365.25*(y+4716))+Math.floor(30.6001*(m+1))+d+B-1524.5;
}

// ─── Fallback: Meeus Sun ──────────────────────────────────────────────────────
function meesusSunLon(date) {
  const JD=julianDay(date),T=(JD-2451545)/36525;
  let L0=280.46646+36000.76983*T+.0003032*T*T; L0=((L0%360)+360)%360;
  let M=357.52911+35999.05029*T-.0001537*T*T; M=((M%360)+360)%360;
  const Mr=M*Math.PI/180;
  const C=(1.914602-.004817*T-.000014*T*T)*Math.sin(Mr)+(0.019993-.000101*T)*Math.sin(2*Mr)+.000289*Math.sin(3*Mr);
  let lon=L0+C;
  const omega=(125.04-1934.136*T)*Math.PI/180;
  lon=lon-.00569-.00478*Math.sin(omega);
  return((lon%360)+360)%360;
}

// ─── Fallback: Meeus Moon ─────────────────────────────────────────────────────
function meesusMoonLon(date) {
  const JD=julianDay(date),T=(JD-2451545)/36525;
  let Lp=218.3165+481267.8813*T; Lp=((Lp%360)+360)%360;
  const Mr =((357.5291+35999.0503*T)%360+360)%360*Math.PI/180;
  const Mpr=((134.9634+477198.8676*T)%360+360)%360*Math.PI/180;
  const Dr =((297.8502+445267.1115*T)%360+360)%360*Math.PI/180;
  const Fr =((93.2721+483202.0175*T)%360+360)%360*Math.PI/180;
  const corr=6.289*Math.sin(Mpr)+1.274*Math.sin(2*Dr-Mpr)+0.658*Math.sin(2*Dr)
    +0.214*Math.sin(2*Mpr)-0.186*Math.sin(Mr)-0.114*Math.sin(2*Fr)
    +0.059*Math.sin(2*Dr-2*Mpr)+0.057*Math.sin(2*Dr-Mr-Mpr)
    +0.053*Math.sin(2*Dr+Mpr)+0.046*Math.sin(2*Dr-Mr)
    +0.041*Math.sin(Mpr-Mr)-0.035*Math.sin(Dr)
    -0.031*Math.sin(Mpr+Mr)-0.015*Math.sin(2*Fr-2*Dr)+0.011*Math.sin(Mpr-4*Dr);
  return(((Lp+corr)%360)+360)%360;
}

// ─── Ascendant (local calc — cannot come from Horizons) ───────────────────────
function calcAscendant(date, latDeg, lonDeg) {
  const JD=julianDay(date),T=(JD-2451545)/36525;
  let GST=280.46061837+360.98564736629*(JD-2451545)+.000387933*T*T-T*T*T/38710000;
  GST=((GST%360)+360)%360;
  const LST=((GST+lonDeg)%360+360)%360;
  const e=(23.439291111-0.013004167*(JD-2451545)/36525)*Math.PI/180;
  const lat=latDeg*Math.PI/180;
  const RAMC=LST*Math.PI/180;
  let asc=Math.atan2(-Math.cos(RAMC),Math.sin(e)*Math.tan(lat)+Math.cos(e)*Math.sin(RAMC))*180/Math.PI;
  return((asc%360)+360)%360;
}

// ─── NASA JPL Horizons fetch ──────────────────────────────────────────────────
const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function horizonsTime(date) {
  const y=date.getFullYear(),m=MONTHS[date.getMonth()],d=String(date.getDate()).padStart(2,'0');
  const h=String(date.getHours()).padStart(2,'0'),min=String(date.getMinutes()).padStart(2,'0');
  return `${y}-${m}-${d} ${h}:${min}`;
}

async function fetchHorizons(naifId, date) {
  const start=horizonsTime(date);
  const stop=horizonsTime(new Date(date.getTime()+60000));
  const url=`https://ssd.jpl.nasa.gov/api/horizons.api?format=json`
    +`&COMMAND='${naifId}'&OBJ_DATA='NO'&MAKE_EPHEM='YES'`
    +`&EPHEM_TYPE='OBSERVER'&CENTER='500@399'`
    +`&START_TIME='${encodeURIComponent(start)}'&STOP_TIME='${encodeURIComponent(stop)}'`
    +`&STEP_SIZE='1m'&QUANTITIES='31'`;
  const resp=await fetch(url);
  if(!resp.ok) throw new Error(`Horizons HTTP ${resp.status}`);
  const data=await resp.json();
  const txt=data.result||'';
  const soe=txt.indexOf('$$SOE');
  if(soe===-1) throw new Error('No SOE in Horizons response');
  const line=txt.substring(soe+6,txt.indexOf('$$EOE')).trim().split('\n')[0];
  const parts=line.split(',');
  const lon=parseFloat(parts[2]);
  if(isNaN(lon)) throw new Error('Could not parse longitude');
  return lon;
}

