// ─── Ecliptic strip ───────────────────────────────────────────────────────────
function buildStrip() {
  const strip=document.getElementById('eclipticStrip'); strip.innerHTML='';
  let left=0;
  for(const s of SIGNS){
    const pct=(s.days/TOTAL_DAYS)*100;
    const b=document.createElement('div');
    b.className='constellation-band'+(s.id==='ophiuchus'?' ophiuchus':'')+(s.id==='scorpius'?' scorpius':'');
    b.id='band_'+s.id; b.style.cssText=`left:${left}%;width:${pct}%`;
    b.innerHTML=`<span>${s.symbol}</span>`; b.title=`${s.name}: ${s.date_approx} (${s.days}d)`;
    strip.appendChild(b); left+=pct;
  }
  ['sun','moon'].forEach(t=>{
    const m=document.createElement('div'); m.className=t+'-marker'; m.id=t+'Marker'; strip.appendChild(m);
  });
}

function placeMarker(id, lon) {
  let totalBefore=0;
  for(const s of SIGNS){
    let inSign=s.id==='pisces'?(lon>=351.5||lon<28.5):(lon>=s.lon_start&&lon<s.lon_end);
    if(inSign){
      let frac=s.id==='pisces'?(lon>=351.5?lon-351.5:lon+(360-351.5))/(38):(lon-s.lon_start)/(s.lon_end-s.lon_start);
      frac=Math.min(Math.max(frac,0),1);
      const pct=((totalBefore+s.days*frac)/TOTAL_DAYS)*100;
      const m=document.getElementById(id); m.style.left=pct+'%'; m.style.display='block'; return;
    }
    totalBefore+=s.days;
  }
}

function highlightBand(id) {
