}

// ─── Render sign card ─────────────────────────────────────────────────────────
function renderCard(prefix, sign, lon, extraRows='') {
  const card=document.getElementById(prefix+'Card');
  card.className='sign-card'+(sign.id==='ophiuchus'?' ophiuchus-card':'');
  document.getElementById(prefix+'Symbol').textContent=sign.symbol;
  document.getElementById(prefix+'Name').textContent=sign.name;
  document.getElementById(prefix+'Dates').textContent=sign.date_approx+' (actual stellar transit)';
  document.getElementById(prefix+'Duration').textContent=sign.days+'d solar transit · '+sign.element+' · '+sign.polarity;
  document.getElementById(prefix+'DataRows').innerHTML=`
    <div class="data-row"><span class="key">Ecliptic Longitude</span><span class="val">${lon.toFixed(4)}°</span></div>
    <div class="data-row"><span class="key">Constellation Boundary</span><span class="val">${sign.id==='pisces'?'351.5° – 28.5°':sign.lon_start+'° – '+sign.lon_end+'°'}</span></div>
    ${extraRows}`;
  const tg=document.getElementById(prefix+'Traits'); tg.innerHTML='';
  sign.traits.forEach(t=>{const d=document.createElement('div');d.className='trait';d.textContent=t;tg.appendChild(d);});
  document.getElementById(prefix+'Desc').textContent=sign.desc;
}

// ─── Main chart generation ────────────────────────────────────────────────────
async function runChart() {
  const dateVal=document.getElementById('bdate').value;
  const err=document.getElementById('errmsg'); err.style.display='none';
  if(!dateVal){err.textContent='Enter a date.';err.style.display='block';return;}
  const timeVal=document.getElementById('btime').value||'12:00';
  const date=new Date(dateVal+'T'+timeVal+':00');
  const latVal=parseFloat(document.getElementById('blat').value);
  const lonVal=parseFloat(document.getElementById('blon').value);

  document.getElementById('calcBtn').disabled=true;
  document.getElementById('loading').classList.add('visible');
  document.getElementById('results').style.display='none';

  // Fetch all bodies from Horizons in parallel, fallback to Meeus for Sun+Moon
  const results={};
  await Promise.all(BODIES.map(async([id,,name])=>{
    try { results[name]=await fetchHorizons(id,date); }
    catch(e) {
      if(name==='Sun')  results[name]=meesusSunLon(date);
      else if(name==='Moon') results[name]=meesusMoonLon(date);
      else results[name]=null;
    }
  }));

  // Ascendant (local calc)
  let ascLon=null, ascSign=null;
  if(!isNaN(latVal)&&!isNaN(lonVal)){
    ascLon=calcAscendant(date,latVal,lonVal);
    ascSign=getSign(ascLon);
  }

  document.getElementById('loading').classList.remove('visible');
  document.getElementById('calcBtn').disabled=false;

  const sunLon=results['Sun'], moonLon=results['Moon'];
  const sunSign=getSign(sunLon), moonSign=getSign(moonLon);

  // Sun card
  placeMarker('sunMarker',sunLon); highlightBand(sunSign.id);
  renderCard('sun',sunSign,sunLon,
    `<div class="data-row"><span class="key">Birth Time</span><span class="val">${timeVal} local</span></div>
     <div class="data-row"><span class="key">Birth Location</span><span class="val">${isNaN(latVal)?'—':latVal+'°N, '+Math.abs(lonVal)+'°W'}</span></div>`);

  // Moon card
  placeMarker('moonMarker',moonLon);
  renderCard('moon',moonSign,moonLon);
  // Style moon name gold→moon color
  document.getElementById('moonName').style.color='var(--moon)';

  // Rising sign row in sun card
  if(ascSign){
    document.getElementById('sunDataRows').innerHTML+=
      `<div class="data-row"><span class="key">Rising Sign (ASC)</span><span class="val ${ascSign.id==='ophiuchus'?'green':''}">${ascSign.symbol} ${ascSign.name} · ${ascLon.toFixed(2)}°</span></div>`;
  }

  // Full natal table
  const tb=document.getElementById('natalBody'); tb.innerHTML='';
  const allBodies=[...BODIES];
  for(const [,sym,name,rowClass] of allBodies){
    const lon=results[name]; if(lon===null) continue;
    const sign=getSign(lon);
    const tr=document.createElement('tr');
    tr.className=[rowClass, sign.id==='ophiuchus'?'oph':'', sign.id==='scorpius'?'sco':''].filter(Boolean).join(' ');
    tr.innerHTML=`<td class="planet-sym">${sym}</td>
      <td class="planet-name">${name}</td>
      <td class="planet-sign">${sign.symbol} ${sign.name}</td>
      <td class="planet-lon">${lon.toFixed(3)}°</td>
      <td style="color:var(--muted);font-size:.68rem">${sign.element}</td>
      <td style="color:var(--muted);font-size:.68rem">${sign.days}d</td>`;
    tb.appendChild(tr);
  }
  // Ascendant row
  if(ascSign){
    const tr=document.createElement('tr'); tr.className='asc-row';
    tr.innerHTML=`<td class="planet-sym">ASC</td>
      <td class="planet-name" style="color:var(--muted)">Rising</td>
      <td class="planet-sign">${ascSign.symbol} ${ascSign.name}</td>
      <td class="planet-lon">${ascLon.toFixed(3)}°</td>
      <td style="color:var(--muted);font-size:.68rem">${ascSign.element}</td>
      <td style="color:var(--muted);font-size:.68rem">${ascSign.days}d</td>`;
    tb.appendChild(tr);
  }

  // Tropical comparison
  const trad=getTrad(date);
  const match=trad.toLowerCase().replace('scorpio','scorpius')===sunSign.id||trad.toLowerCase()===sunSign.id;
  document.getElementById('comparison').innerHTML=`
    <div class="comparison-title">Tropical vs Sidereal — Sun Sign</div>
    <div class="data-row"><span class="key">Western Tropical</span><span class="val">${trad}</span></div>
    <div class="data-row"><span class="key">Sidereal Corrected</span><span class="val ${sunSign.id==='ophiuchus'?'green':''}">${sunSign.name}</span></div>
    <div class="data-row"><span class="key">Agreement</span><span class="${match?'match':'mismatch'}">${match?'✓ Signs align':'✗ Displaced ~23–25° by precession'}</span></div>`;

  document.getElementById('results').style.display='block';
}

// ─── Init ─────────────────────────────────────────────────────────────────────
buildStrip();
buildTable();
window.addEventListener('load',()=>runChart());
</script>
</body>
</html>
