const TOTAL_DAYS = SIGNS.reduce((a,s)=>a+s.days,0);

function getSign(lon) {
  for (const s of SIGNS) {
    if (s.id==='pisces') { if (lon>=351.5||lon<28.5) return s; }
    else { if (lon>=s.lon_start && lon<s.lon_end) return s; }
  }
  return SIGNS[0];
}

// Traditional tropical (for comparison)
const TRAD=[
  {name:'Capricorn',start:[12,22],end:[1,19]},{name:'Aquarius',start:[1,20],end:[2,18]},
  {name:'Pisces',start:[2,19],end:[3,20]},{name:'Aries',start:[3,21],end:[4,19]},
  {name:'Taurus',start:[4,20],end:[5,20]},{name:'Gemini',start:[5,21],end:[6,20]},
  {name:'Cancer',start:[6,21],end:[7,22]},{name:'Leo',start:[7,23],end:[8,22]},
  {name:'Virgo',start:[8,23],end:[9,22]},{name:'Libra',start:[9,23],end:[10,22]},
  {name:'Scorpio',start:[10,23],end:[11,21]},{name:'Sagittarius',start:[11,22],end:[12,21]},
];
function getTrad(date) {
  const m=date.getMonth()+1,d=date.getDate();
  for (const t of TRAD) {
    const [sm,sd]=t.start,[em,ed]=t.end;
    if(sm<=em){if((m===sm&&d>=sd)||(m>sm&&m<em)||(m===em&&d<=ed))return t.name;}
    else{if((m===sm&&d>=sd)||m>sm||(m===em&&d<=ed))return t.name;}
  } return 'Capricorn';
}

// ─── Julian Day ───────────────────────────────────────────────────────────────
function julianDay(date) {
  let y=date.getFullYear(),m=date.getMonth()+1;
  const d=date.getDate()+(date.getHours()+date.getMinutes()/60+date.getSeconds()/3600)/24;
  if(m<=2){y--;m+=12;}
  const A=Math.floor(y/100),B=2-A+Math.floor(A/4);
  return Math.floor(365.25*(y+4716))+Math.floor(30.6001*(m+1))+d+B-1524.5;
}

// ─── Fallback: Meeus Sun ──────────────────────────────────────────────────────
function meesusSunLon(date) {
  const JD=julianDay(date),T=(JD-2451545)/36525;
  let L0=280.46646+36000.76983*T+.0003032*T*T; L0=((L0%360)+360)%360;
  let M=357.52911+35999.05029*T-.0001537*T*T; M=((M%360)+360)%360;
  const Mr=M*Math.PI/180;
  const C=(1.914602-.004817*T-.000014*T*T)*Math.sin(Mr)+(0.019993-.000101*T)*Math.sin(2*Mr)+.000289*Math.sin(3*Mr);
  let lon=L0+C;
  const omega=(125.04-1934.136*T)*Math.PI/180;
  lon=lon-.00569-.00478*Math.sin(omega);
  return((lon%360)+360)%360;
}

// ─── Fallback: Meeus Moon ─────────────────────────────────────────────────────
function meesusMoonLon(date) {
  const JD=julianDay(date),T=(JD-2451545)/36525;
  let Lp=218.3165+481267.8813*T; Lp=((Lp%360)+360)%360;
  const Mr =((357.5291+35999.0503*T)%360+360)%360*Math.PI/180;
  const Mpr=((134.9634+477198.8676*T)%360+360)%360*Math.PI/180;
  const Dr =((297.8502+445267.1115*T)%360+360)%360*Math.PI/180;
  const Fr =((93.2721+483202.0175*T)%360+360)%360*Math.PI/180;
  const corr=6.289*Math.sin(Mpr)+1.274*Math.sin(2*Dr-Mpr)+0.658*Math.sin(2*Dr)
    +0.214*Math.sin(2*Mpr)-0.186*Math.sin(Mr)-0.114*Math.sin(2*Fr)
    +0.059*Math.sin(2*Dr-2*Mpr)+0.057*Math.sin(2*Dr-Mr-Mpr)
    +0.053*Math.sin(2*Dr+Mpr)+0.046*Math.sin(2*Dr-Mr)
    +0.041*Math.sin(Mpr-Mr)-0.035*Math.sin(Dr)
    -0.031*Math.sin(Mpr+Mr)-0.015*Math.sin(2*Fr-2*Dr)+0.011*Math.sin(Mpr-4*Dr);
  return(((Lp+corr)%360)+360)%360;
}

// ─── Ascendant (local calc — cannot come from Horizons) ───────────────────────
function calcAscendant(date, latDeg, lonDeg) {
  const JD=julianDay(date),T=(JD-2451545)/36525;
  let GST=280.46061837+360.98564736629*(JD-2451545)+.000387933*T*T-T*T*T/38710000;
  GST=((GST%360)+360)%360;
  const LST=((GST+lonDeg)%360+360)%360;
  const e=(23.439291111-0.013004167*(JD-2451545)/36525)*Math.PI/180;
  const lat=latDeg*Math.PI/180;
  const RAMC=LST*Math.PI/180;
  let asc=Math.atan2(-Math.cos(RAMC),Math.sin(e)*Math.tan(lat)+Math.cos(e)*Math.sin(RAMC))*180/Math.PI;
  return((asc%360)+360)%360;
}

// ─── NASA JPL Horizons fetch ──────────────────────────────────────────────────
const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function horizonsTime(date) {
  const y=date.getFullYear(),m=MONTHS[date.getMonth()],d=String(date.getDate()).padStart(2,'0');
  const h=String(date.getHours()).padStart(2,'0'),min=String(date.getMinutes()).padStart(2,'0');
  return `${y}-${m}-${d} ${h}:${min}`;
}

async function fetchHorizons(naifId, date) {
  const start=horizonsTime(date);
  const stop=horizonsTime(new Date(date.getTime()+60000));
  const url=`https://ssd.jpl.nasa.gov/api/horizons.api?format=json`
    +`&COMMAND='${naifId}'&OBJ_DATA='NO'&MAKE_EPHEM='YES'`
    +`&EPHEM_TYPE='OBSERVER'&CENTER='500@399'`
    +`&START_TIME='${encodeURIComponent(start)}'&STOP_TIME='${encodeURIComponent(stop)}'`
    +`&STEP_SIZE='1m'&QUANTITIES='31'`;
  const resp=await fetch(url);
  if(!resp.ok) throw new Error(`Horizons HTTP ${resp.status}`);
  const data=await resp.json();
  const txt=data.result||'';
  const soe=txt.indexOf('$$SOE');
  if(soe===-1) throw new Error('No SOE in Horizons response');
  const line=txt.substring(soe+6,txt.indexOf('$$EOE')).trim().split('\n')[0];
  const parts=line.split(',');
  const lon=parseFloat(parts[2]);
  if(isNaN(lon)) throw new Error('Could not parse longitude');
  return lon;
}

// Body definitions: [naifId, symbol, display name, row class]
const BODIES=[
  ['10',  '☉', 'Sun',     'sun-row'],
  ['301', '☽', 'Moon',    'moon-row'],
  ['199', '☿', 'Mercury', ''],
  ['299', '♀', 'Venus',   ''],
  ['499', '♂', 'Mars',    ''],
  ['599', '♃', 'Jupiter', ''],
  ['699', '♄', 'Saturn',  ''],
  ['799', '⛢', 'Uranus',  ''],
  ['899', '♆', 'Neptune', ''],
  ['999', '♇', 'Pluto',   ''],
];

// ─── Ecliptic strip ───────────────────────────────────────────────────────────
function buildStrip() {
  const strip=document.getElementById('eclipticStrip'); strip.innerHTML='';
  let left=0;
  for(const s of SIGNS){
    const pct=(s.days/TOTAL_DAYS)*100;
    const b=document.createElement('div');
    b.className='constellation-band'+(s.id==='ophiuchus'?' ophiuchus':'')+(s.id==='scorpius'?' scorpius':'');
    b.id='band_'+s.id; b.style.cssText=`left:${left}%;width:${pct}%`;
    b.innerHTML=`<span>${s.symbol}</span>`; b.title=`${s.name}: ${s.date_approx} (${s.days}d)`;
    strip.appendChild(b); left+=pct;
  }
  ['sun','moon'].forEach(t=>{
    const m=document.createElement('div'); m.className=t+'-marker'; m.id=t+'Marker'; strip.appendChild(m);
  });
}

function placeMarker(id, lon) {
  let totalBefore=0;
  for(const s of SIGNS){
    let inSign=s.id==='pisces'?(lon>=351.5||lon<28.5):(lon>=s.lon_start&&lon<s.lon_end);
    if(inSign){
      let frac=s.id==='pisces'?(lon>=351.5?lon-351.5:lon+(360-351.5))/(38):(lon-s.lon_start)/(s.lon_end-s.lon_start);
      frac=Math.min(Math.max(frac,0),1);
      const pct=((totalBefore+s.days*frac)/TOTAL_DAYS)*100;
      const m=document.getElementById(id); m.style.left=pct+'%'; m.style.display='block'; return;
    }
    totalBefore+=s.days;
  }
}

function highlightBand(id) {
  document.querySelectorAll('.constellation-band').forEach(b=>b.classList.remove('active'));
  const b=document.getElementById('band_'+id); if(b) b.classList.add('active');
}

// ─── Build reference table ────────────────────────────────────────────────────
function buildTable(){
  const tb=document.getElementById('allSignsBody');
  for(const s of SIGNS){
    const tr=document.createElement('tr');
    if(s.id==='ophiuchus')tr.className='oph'; if(s.id==='scorpius')tr.className='sco';
    tr.innerHTML=`<td>${s.name}</td><td>${s.symbol}</td><td>${s.date_approx.split('–')[0].trim()}</td><td>${(s.date_approx.split('–')[1]||'').trim()}</td><td>${s.days}d</td><td style="color:var(--muted);font-style:italic">${s.trad}</td>`;
    tb.appendChild(tr);
  }
}
function toggleTable(){
  const t=document.getElementById('allSigns'); t.classList.toggle('open');
  document.querySelector('.all-signs-toggle').textContent=t.classList.contains('open')?'▾ Full 13-Sign Reference Table':'▸ Full 13-Sign Reference Table';
}

// ─── Render sign card ─────────────────────────────────────────────────────────
function renderCard(prefix, sign, lon, extraRows='') {
  const card=document.getElementById(prefix+'Card');
  card.className='sign-card'+(sign.id==='ophiuchus'?' ophiuchus-card':'');
  document.getElementById(prefix+'Symbol').textContent=sign.symbol;
  document.getElementById(prefix+'Name').textContent=sign.name;
  document.getElementById(prefix+'Dates').textContent=sign.date_approx+' (actual stellar transit)';
  document.getElementById(prefix+'Duration').textContent=sign.days+'d solar transit · '+sign.element+' · '+sign.polarity;
  document.getElementById(prefix+'DataRows').innerHTML=`
    <div class="data-row"><span class="key">Ecliptic Longitude</span><span class="val">${lon.toFixed(4)}°</span></div>
    <div class="data-row"><span class="key">Constellation Boundary</span><span class="val">${sign.id==='pisces'?'351.5° – 28.5°':sign.lon_start+'° – '+sign.lon_end+'°'}</span></div>
    ${extraRows}`;
  const tg=document.getElementById(prefix+'Traits'); tg.innerHTML='';
  sign.traits.forEach(t=>{const d=document.createElement('div');d.className='trait';d.textContent=t;tg.appendChild(d);});
  document.getElementById(prefix+'Desc').textContent=sign.desc;
}

// ─── Main chart generation ────────────────────────────────────────────────────
async function runChart() {
  const dateVal=document.getElementById('bdate').value;
  const err=document.getElementById('errmsg'); err.style.display='none';
  if(!dateVal){err.textContent='Enter a date.';err.style.display='block';return;}
  const timeVal=document.getElementById('btime').value||'12:00';
  const date=new Date(dateVal+'T'+timeVal+':00');
  const latVal=parseFloat(document.getElementById('blat').value);
  const lonVal=parseFloat(document.getElementById('blon').value);

  document.getElementById('calcBtn').disabled=true;
  document.getElementById('loading').classList.add('visible');
  document.getElementById('results').style.display='none';

  // Fetch all bodies from Horizons in parallel, fallback to Meeus for Sun+Moon
  const results={};
  await Promise.all(BODIES.map(async([id,,name])=>{
    try { results[name]=await fetchHorizons(id,date); }
    catch(e) {
      if(name==='Sun')  results[name]=meesusSunLon(date);
      else if(name==='Moon') results[name]=meesusMoonLon(date);
      else results[name]=null;
    }
  }));

  // Ascendant (local calc)
  let ascLon=null, ascSign=null;
  if(!isNaN(latVal)&&!isNaN(lonVal)){
    ascLon=calcAscendant(date,latVal,lonVal);
    ascSign=getSign(ascLon);
  }

  document.getElementById('loading').classList.remove('visible');
  document.getElementById('calcBtn').disabled=false;

  const sunLon=results['Sun'], moonLon=results['Moon'];
  const sunSign=getSign(sunLon), moonSign=getSign(moonLon);

  // Sun card
  placeMarker('sunMarker',sunLon); highlightBand(sunSign.id);
  renderCard('sun',sunSign,sunLon,
    `<div class="data-row"><span class="key">Birth Time</span><span class="val">${timeVal} local</span></div>
     <div class="data-row"><span class="key">Birth Location</span><span class="val">${isNaN(latVal)?'—':latVal+'°N, '+Math.abs(lonVal)+'°W'}</span></div>`);

  // Moon card
  placeMarker('moonMarker',moonLon);
  renderCard('moon',moonSign,moonLon);
  // Style moon name gold→moon color
  document.getElementById('moonName').style.color='var(--moon)';

  // Rising sign row in sun card
  if(ascSign){
    document.getElementById('sunDataRows').innerHTML+=
      `<div class="data-row"><span class="key">Rising Sign (ASC)</span><span class="val ${ascSign.id==='ophiuchus'?'green':''}">${ascSign.symbol} ${ascSign.name} · ${ascLon.toFixed(2)}°</span></div>`;
  }

  // Full natal table
  const tb=document.getElementById('natalBody'); tb.innerHTML='';
  const allBodies=[...BODIES];
  for(const [,sym,name,rowClass] of allBodies){
    const lon=results[name]; if(lon===null) continue;
    const sign=getSign(lon);
    const tr=document.createElement('tr');
    tr.className=[rowClass, sign.id==='ophiuchus'?'oph':'', sign.id==='scorpius'?'sco':''].filter(Boolean).join(' ');
    tr.innerHTML=`<td class="planet-sym">${sym}</td>
      <td class="planet-name">${name}</td>
      <td class="planet-sign">${sign.symbol} ${sign.name}</td>
      <td class="planet-lon">${lon.toFixed(3)}°</td>
      <td style="color:var(--muted);font-size:.68rem">${sign.element}</td>
      <td style="color:var(--muted);font-size:.68rem">${sign.days}d</td>`;
    tb.appendChild(tr);
  }
  // Ascendant row
  if(ascSign){
    const tr=document.createElement('tr'); tr.className='asc-row';
    tr.innerHTML=`<td class="planet-sym">ASC</td>
      <td class="planet-name" style="color:var(--muted)">Rising</td>
      <td class="planet-sign">${ascSign.symbol} ${ascSign.name}</td>
      <td class="planet-lon">${ascLon.toFixed(3)}°</td>
      <td style="color:var(--muted);font-size:.68rem">${ascSign.element}</td>
      <td style="color:var(--muted);font-size:.68rem">${ascSign.days}d</td>`;
    tb.appendChild(tr);
  }

  // Tropical comparison
  const trad=getTrad(date);
  const match=trad.toLowerCase().replace('scorpio','scorpius')===sunSign.id||trad.toLowerCase()===sunSign.id;
  document.getElementById('comparison').innerHTML=`
    <div class="comparison-title">Tropical vs Sidereal — Sun Sign</div>
    <div class="data-row"><span class="key">Western Tropical</span><span class="val">${trad}</span></div>
    <div class="data-row"><span class="key">Sidereal Corrected</span><span class="val ${sunSign.id==='ophiuchus'?'green':''}">${sunSign.name}</span></div>
    <div class="data-row"><span class="key">Agreement</span><span class="${match?'match':'mismatch'}">${match?'✓ Signs align':'✗ Displaced ~23–25° by precession'}</span></div>`;

  document.getElementById('results').style.display='block';
}

// ─── Init ─────────────────────────────────────────────────────────────────────
buildStrip();
buildTable();
window.addEventListener('load',()=>runChart());
</script>
